const MISSING_REASON: Partial<Record<ToolCapabilityId, PublicCapabilityState["reasonCode"]>> = {
  "shell.bash": "TOOLCHAIN_BASH_REQUIRED",
  "vcs.git": "TOOLCHAIN_GIT_REQUIRED",
